CREATE MATERIALIZED VIEW worldchain.dex_swaps_view (`block_number` UInt64, `transaction_hash` FixedString(66), `pair_address` FixedString(42), `is_v2` UInt8, `is_v3` UInt8, `data` String) ENGINE = MergeTree ORDER BY (block_number, pair_address) SETTINGS index_granularity = 8192 AS SELECT block_number, tx_hash AS transaction_hash, address AS pair_address, topic0 = '0xd78ad95fa46c994b6551d0da85fc275fe613ce37657fb8d5e3d130840159d822' AS is_v2, topic0 = '0xc42079f94a6350d7e6235f29174924f928cc2ac818eb64fed8004e115fbcca67' AS is_v3, data FROM worldchain.world_logs WHERE topic0 IN ('0xd78ad95fa46c994b6551d0da85fc275fe613ce37657fb8d5e3d130840159d822', '0xc42079f94a6350d7e6235f29174924f928cc2ac818eb64fed8004e115fbcca67');
CREATE VIEW worldchain.erc20_transfers_view (`block_number` UInt64, `transaction_hash` FixedString(66), `token_address` FixedString(42), `from_address` String, `to_address` String, `amount_raw` UInt256, `amount_normalized` Float64, `timestamp` DateTime64(3)) AS SELECT l.block_number, l.tx_hash AS transaction_hash, l.address AS token_address, concat('0x', substring(l.topic1, 27, 40)) AS from_address, concat('0x', substring(l.topic2, 27, 40)) AS to_address, reinterpretAsUInt256(reverse(unhex(substring(l.data, 3)))) AS amount_raw, toUInt256(amount_raw) / 1000000000000000000. AS amount_normalized, b.timestamp FROM worldchain.world_logs AS l LEFT JOIN worldchain.world_blocks AS b ON l.block_number = b.block_number WHERE l.topic0 = '0xddf252ad1be2c89b69c2b068fc378daa952ba7f163c4a11628f55a4df523b3ef';
CREATE MATERIALIZED VIEW worldchain.price_history_view (`block_number` UInt64, `timestamp` DateTime64(3), `asset` String, `price_usd` Float64) ENGINE = MergeTree ORDER BY (block_number, asset) SETTINGS index_granularity = 8192 AS SELECT block_number, ingested_at AS timestamp, multiIf(address = '0x8Bb2943AB030E3eE05a58d9832525B4f60A97FA0', 'WLD', address = '0xe1d72a719171DceAB9499757EB9d5AEb9e8D64A6', 'ETH', address = '0xF4301686AfF4eE36d70c718a9e62309b53862BE8', 'USDC', 'UNKNOWN') AS asset, reinterpretAsInt256(reverse(unhex(substring(data, 3)))) / 100000000. AS price_usd FROM worldchain.world_logs WHERE (topic0 = '0x0559884fd3a460db30fea510563813e07234719452a4306a4e3e481b29a285d3') AND (address IN ('0x8Bb2943AB030E3eE05a58d9832525B4f60A97FA0', '0xe1d72a719171DceAB9499757EB9d5AEb9e8D64A6', '0xF4301686AfF4eE36d70c718a9e62309b53862BE8'));
CREATE MATERIALIZED VIEW worldchain.token_balances_mv TO worldchain.token_balances (`token_address` FixedString(42), `owner_address` String, `balance_change` Int256) AS SELECT l.address AS token_address, concat('0x', substring(l.topic1, 27, 40)) AS owner_address, -toInt256(reinterpretAsUInt256(reverse(unhex(substring(l.data, 3))))) AS balance_change FROM worldchain.world_logs AS l WHERE (l.topic0 = '0xddf252ad1be2c89b69c2b068fc378daa952ba7f163c4a11628f55a4df523b3ef') AND (l.is_canonical = 1) UNION ALL SELECT l.address, concat('0x', substring(l.topic2, 27, 40)), toInt256(reinterpretAsUInt256(reverse(unhex(substring(l.data, 3))))) FROM worldchain.world_logs AS l WHERE (l.topic0 = '0xddf252ad1be2c89b69c2b068fc378daa952ba7f163c4a11628f55a4df523b3ef') AND (l.is_canonical = 1);
CREATE MATERIALIZED VIEW worldchain.uniswap_v3_prices_view (`block_number` UInt64, `transaction_hash` FixedString(66), `pool_address` FixedString(42), `sqrt_price_x96` UInt256, `price_raw` Float64) ENGINE = MergeTree ORDER BY (block_number, pool_address) SETTINGS index_granularity = 8192 AS SELECT block_number, tx_hash AS transaction_hash, address AS pool_address, reinterpretAsUInt256(reverse(unhex(substring(data, 131, 64)))) AS sqrt_price_x96, pow(sqrt_price_x96 / 7.922816251426434e28, 2) AS price_raw FROM worldchain.world_logs WHERE topic0 = '0xc42079f94a6350d7e6235f29174924f928cc2ac818eb64fed8004e115fbcca67';
CREATE VIEW worldchain.view_human_analytics (`day` DateTime, `active_human_addresses` UInt64, `human_transactions` UInt64, `total_human_gas_used` UInt64) AS SELECT toStartOfDay(b.timestamp) AS day, countDistinct(t.from_address) AS active_human_addresses, count(t.tx_hash) AS human_transactions, sum(t.gas_used) AS total_human_gas_used FROM worldchain.world_transactions AS t INNER JOIN worldchain.world_blocks AS b ON b.block_number = t.block_number INNER JOIN worldchain.world_address_labels AS l ON l.address = t.from_address WHERE (l.world_id_flag = 1) AND (t.is_canonical = 1) GROUP BY day ORDER BY day DESC;
CREATE MATERIALIZED VIEW worldchain.view_live_oracle_prices TO worldchain.world_token_prices (`token_address` String, `minute_bucket` DateTime, `price_usd` Float64, `liquidity_usd` UInt8, `source_pair` String) AS SELECT multiIf(address = '0x8Bb2943AB030E3eE05a58d9832525B4f60A97FA0', '0x2cfc85d8e48f8eab294be644d9e25c3030863003', address = '0xe1d72a719171DceAB9499757EB9d5AEb9e8D64A6', '0x4200000000000000000000000000000000000006', address = '0xdD91675235C37a47597c053807d61Da27Ae1AE6C', '0x03c7054bcb39f7b2e5b2c7acb37583e32d70cfa3', address = '0xF4301686AfF4eE36d70c718a9e62309b53862BE8', '0x79A02482A880bCE3F13e09Da970dC34db4CD24d1', address = '0x78ce3664d1582e14270092ea9817f111ac53524b', '0x2416092f143378750bb29b79ed961ab195cceea5', address) AS token_address, toStartOfMinute(ingested_at) AS minute_bucket, reinterpretAsFloat64(unhex(substring(data, 3, 64))) / 100000000 AS price_usd, 0 AS liquidity_usd, 'Native_Oracle' AS source_pair FROM worldchain.world_logs WHERE (address IN ('0x8Bb2943AB030E3eE05a58d9832525B4f60A97FA0', '0xe1d72a719171DceAB9499757EB9d5AEb9e8D64A6', '0xdD91675235C37a47597c053807d61Da27Ae1AE6C', '0xF4301686AfF4eE36d70c718a9e62309b53862BE8', '0x78ce3664d1582e14270092ea9817f111ac53524b')) AND (topic0 = '0x0559884fd3a46039e246a27e7cb3f1a1c09d8bf002a79246102aa6bc4d7c58ed');
CREATE VIEW worldchain.view_token_transfers (`chain_id` UInt32, `block_number` UInt64, `tx_hash` FixedString(32), `log_index` UInt32, `token_address` FixedString(20), `from_address` String, `to_address` String, `raw_amount` UInt256) AS SELECT l.chain_id, l.block_number, l.tx_hash, l.log_index, l.address AS token_address, concat('0x', substring(l.topic1, 27, 40)) AS from_address, concat('0x', substring(l.topic2, 27, 40)) AS to_address, multiIf((l.data != '0x') AND (length(l.data) >= 66), reinterpretAsUInt256(unhex(substring(l.data, 3))), l.topic3 != '', reinterpretAsUInt256(unhex(substring(l.topic3, 3))), 0) AS raw_amount FROM worldchain.world_logs AS l WHERE (l.topic0 = '0xddf252ad1be2c89b69c2b068fc378daa952ba7f163c4a11628f55a4df523b3ef') AND (l.is_canonical = 1);
CREATE VIEW worldchain.view_verified_human_activity (`block_number` UInt64, `tx_hash` FixedString(32), `smart_wallet_address` FixedString(20), `human_action` String, `gas_used` UInt64) AS SELECT t.block_number, t.tx_hash, t.from_address AS smart_wallet_address, multiIf(l.label = 'WorldIDRouter', 'Verification', l.label LIKE '%Grant%', 'Claim', 'Transaction') AS human_action, t.gas_used FROM worldchain.world_transactions AS t INNER JOIN worldchain.world_address_labels AS l ON l.address = t.to_address WHERE (l.label_category IN ('Identity', 'Grants')) AND (t.is_canonical = 1);
CREATE MATERIALIZED VIEW worldchain.world_dex_ohlcv_1m (`pair_address` FixedString(20), `minute_bucket` DateTime, `open` AggregateFunction(argMin, Float64, DateTime), `high` AggregateFunction(max, Float64), `low` AggregateFunction(min, Float64), `close` AggregateFunction(argMax, Float64, DateTime), `volume_token_in` AggregateFunction(sum, Float64), `volume_token_out` AggregateFunction(sum, Float64)) ENGINE = AggregatingMergeTree ORDER BY (pair_address, minute_bucket) SETTINGS index_granularity = 8192 AS SELECT pair_address, toStartOfMinute(timestamp) AS minute_bucket, argMinState(price_native, timestamp) AS open, maxState(price_native) AS high, minState(price_native) AS low, argMaxState(price_native, timestamp) AS close, sumState(amount_in) AS volume_token_in, sumState(amount_out) AS volume_token_out FROM worldchain.world_dex_trades GROUP BY pair_address, minute_bucket;
